    // Aviso do limite de doses únicas (Lançar venda)
    "⚠️ A unidade já atingiu as {limite} doses únicas que contam para a meta em {mes}. Esta venda gera comissão normalmente, mas não conta para a meta nem para o ranking. Que tal oferecer Drybelly, Retention ou Force?": "⚠️ La sede ya llegó a las {limite} dosis únicas que cuentan para la meta en {mes}. Esta venta genera comisión normalmente, pero no cuenta para la meta ni para el ranking. ¿Qué tal ofrecer Drybelly, Retention o Force?",
