    "Dinheiro que entrou, digitado dia a dia na aba Metas → Movimento do dia. Não é a comissão (a comissão fica no Fechamento).": "Dinero que entró, cargado día a día en Metas → Movimiento del día. No es la comisión (la comisión está en el Cierre).",
