    "Entradas (automático)": "Altas (automático)",
    "Entradas = planos vendidos no dia (automático, igual ao Dashboard; o PRATIQUE NUTRI é adicional e não entra). Cancelamentos e faturamento são digitados por Líder, Mentor ou Admin. Faturamento é o dinheiro que entrou no dia — não é a comissão.": "Altas = planes vendidos en el día (automático, igual que el Dashboard; PRATIQUE NUTRI es adicional y no entra). Cancelaciones y facturación las cargan Líder, Mentor o Admin. Facturación es el dinero que entró en el día; no es la comisión.",
