    // Movimentação (acumulado do mês)
    "O acumulado ficou MENOR que o do lançamento anterior ({dia}). O valor do dia vai ficar negativo. Gravar mesmo assim?": "El acumulado quedó MENOR que el del registro anterior ({dia}). El valor del día va a quedar negativo. ¿Guardar igual?",
    "Não foi possível gravar a movimentação: {erro}": "No se pudo guardar el movimiento: {erro}",
    "Acumulado do mês até": "Acumulado del mes hasta",
    "Digite os números do dia 1º do mês até este dia (normalmente ontem). Ex.: no dia 15 digite de 01 a 14. No dia 1º, digite o mês anterior fechado (escolha o último dia dele). O sistema calcula o valor de cada dia pela diferença.": "Ingresá los números desde el día 1 del mes hasta este día (normalmente ayer). Ej.: el día 15 ingresá del 01 al 14. El día 1, ingresá el mes anterior cerrado (elegí su último día). El sistema calcula el valor de cada día por la diferencia.",
    "Planos vendidos (igual ao Dashboard; o PRATIQUE NUTRI é adicional e não entra).": "Planes vendidos (igual que el Dashboard; PRATIQUE NUTRI es adicional y no cuenta).",
    "no mês até {dia} · no dia: {qtd}": "en el mes hasta {dia} · en el día: {qtd}",
    "no dia: {valor}": "en el día: {valor}",
    "\"No dia\" = diferença para o lançamento de {dia}.": "\"En el día\" = diferencia con el registro del {dia}.",
    "Gravar movimentação": "Guardar movimiento",
    "Só Líder, Mentor e Admin lançam a movimentação.": "Solo Líder, Mentor y Admin cargan el movimiento.",
    "acum. {valor}": "acum. {valor}",
    "Movimentação por dia": "Movimiento por día",
    "Valor de cada dia = acumulado do mês daquele dia menos o acumulado do lançamento anterior. Embaixo, em cinza, o acumulado do mês. Faturamento é o dinheiro que entrou — não é a comissão.": "Valor de cada día = acumulado del mes de ese día menos el acumulado del registro anterior. Abajo, en gris, el acumulado del mes. La facturación es el dinero que entró — no es la comisión.",
    "Escolha uma unidade no seletor do topo para lançar a movimentação.": "Elegí una sede en el selector de arriba para cargar el movimiento.",
    "soma de {qtd} dias": "suma de {qtd} días",
    "Movimentação": "Movimiento",
    "Ativos atuais, entradas, cancelamentos e faturamento da unidade. Atualize diariamente.": "Socios activos, altas, bajas y facturación de la sede. Actualizá todos los días.",
    "{qtd} lançamento(s) no período": "{qtd} registro(s) en el período",
    "automático · no dia: {qtd}": "automático · en el día: {qtd}",
    "acumulado do mês": "acumulado del mes",
    "desde o dia 1º: {valor}": "desde el día 1: {valor}",
    "Digite os números do dia 1º do mês até o dia escolhido. \"Este mês\" = do dia 1º até agora, igual ao \"Este mês\" do TECACE (pode gravar de novo no fim do dia, o número é trocado). No dia 1º, use \"Mês passado\" para gravar o mês anterior fechado. O sistema calcula o valor de cada dia pela diferença.": "Ingresá los números desde el día 1 del mes hasta el día elegido. \"Este mes\" = del día 1 hasta ahora, igual que el \"Este mes\" del TECACE (podés guardar de nuevo al final del día, el número se reemplaza). El día 1, usá \"Mes pasado\" para guardar el mes anterior cerrado. El sistema calcula el valor de cada día por la diferencia.",
    "Escolher um dia": "Elegir un día",
    "automático": "automático",
    "{valor} no dia": "{valor} en el día",
    "{valor} cancelamentos no dia": "{valor} bajas en el día",
    "Escolha um período.": "Elegí un período.",
    "O período precisa ficar dentro de um mês só (ex.: \"Este mês\", \"Hoje\" ou \"Mês passado\").": "El período tiene que quedar dentro de un solo mes (ej.: \"Este mes\", \"Hoy\" o \"Mes pasado\").",
    "O período não pode terminar depois de hoje.": "El período no puede terminar después de hoy.",
    "{valor} no dia {dia}": "{valor} el día {dia}",
    "acum. do mês: {valor}": "acum. del mes: {valor}",
    "cancel.": "bajas",
    "Período dos números": "Período de los números",
    "Escolha o mesmo período que você filtrou no TECACE e digite os números dele. \"Este mês\" = do dia 1º até agora; \"Hoje\" = só hoje; \"Mês passado\" = o mês anterior fechado. Pode gravar de novo: o número é trocado. O sistema guarda o acumulado do mês e calcula cada dia pela diferença.": "Elegí el mismo período que filtraste en el TECACE e ingresá sus números. \"Este mes\" = del día 1 hasta ahora; \"Hoy\" = solo hoy; \"Mes pasado\" = el mes anterior cerrado. Podés guardar de nuevo: el número se reemplaza. El sistema guarda el acumulado del mes y calcula cada día por la diferencia.",
    "Atenção: não há lançamento de {de} a {ate}. Para o acumulado do mês ficar certo, lance esses dias ou use \"Este mês\".": "Atención: no hay registro del {de} al {ate}. Para que el acumulado del mes quede bien, cargá esos días o usá \"Este mes\".",
    "Alunos ativos hoje": "Socios activos hoy",
    "Últimos 15 dias": "Últimos 15 días",
    "Digite os números do dia 1º do mês até a data. \"Este mês\" = até hoje; \"Ontem\" = até ontem (para quem esqueceu de lançar); \"Escolher dia\" = até o dia escolhido. Pode gravar de novo: o número é trocado. O \"+\" na frente mostra quanto somou desde o lançamento anterior.": "Ingresá los números desde el día 1 del mes hasta la fecha. \"Este mes\" = hasta hoy; \"Ayer\" = hasta ayer (si te olvidaste de cargarlo); \"Elegir día\" = hasta el día elegido. Podés guardar de nuevo: el número se reemplaza. El \"+\" adelante muestra cuánto sumó desde el registro anterior.",
