    "Sáb/dom": "Sáb/dom",
    "Conta sozinho como enviado quando o login da Recepção clica em Copiar ou Enviar no WhatsApp Fechamento (Relatórios, período Hoje, a própria unidade) no horário: manhã das 13h30 às 15h · noite das 21h30 às 23h · sábado, domingo e feriado das 12h às 13h. Depois do prazo ainda conta, como atrasado (até 17h59 de manhã e até 23h59 à noite). Se a recepção mandou de outro jeito, o Líder confere no grupo de vendas e confirma.": "Cuenta solo como enviado cuando el login de Recepción hace clic en Copiar o Enviar en el WhatsApp de Cierre (Informes, período Hoy, su propia sede) en el horario: mañana de 13h30 a 15h · noche de 21h30 a 23h · sábado, domingo y feriado de 12h a 13h. Después del plazo todavía cuenta, como atrasado (hasta 17h59 a la mañana y hasta 23h59 a la noche). Si la recepción lo mandó de otra forma, el Líder controla en el grupo de ventas y confirma.",
