    "O sistema não registrou o envio (o registro automático só conta o clique em Copiar ou Enviar no WhatsApp Fechamento, pelo login da Recepção, dentro do horário). A sua resposta fica registrada com o seu nome.": "El sistema no registró el envío (solo cuenta el clic en Copiar o Enviar del WhatsApp de Cierre, desde el login de Recepción, dentro del horario). Tu respuesta queda registrada con tu nombre.",
