    "O banco também confere esta ação: rode no Supabase o SQL de sql/2026-11-06-permissoes-acoes/ para poder mudar.": "La base también controla esta acción: corré en Supabase el SQL de sql/2026-11-06-permissoes-acoes/ para poder cambiarla.",
    "Só vale para: {niveis}.": "Solo vale para: {niveis}.",
