    "Ligue ou desligue o que cada nível vê e faz. A permissão diz O QUE a pessoa pode; a unidade continua dizendo ONDE (o Mentor só nas unidades dele, o Líder e a Recepção só na deles). Bolinha amarela = mudado em relação ao padrão. O cadeado = travado. Ícone de banco = o banco também confere.": "Prendé o apagá lo que cada nivel ve y hace. El permiso dice QUÉ puede la persona; la sede sigue diciendo DÓNDE (el Mentor solo en sus sedes, el Líder y Recepción solo en la suya). Punto amarillo = cambiado respecto del estándar. Candado = bloqueado. Ícono de base = la base también controla.",
