    "Ligue ou desligue o que cada nível vê. A permissão diz O QUE a pessoa vê; a unidade continua dizendo ONDE (o Mentor só nas unidades dele, o Líder e a Recepção só na deles). Bolinha amarela = mudado em relação ao padrão. O cadeado = travado.": "Activá o desactivá lo que ve cada nivel. El permiso dice QUÉ ve la persona; la sede sigue diciendo DÓNDE (el Mentor solo en sus sedes, el Líder y la Recepción solo en la suya). Punto amarillo = cambiado respecto al estándar. Candado = bloqueado.",
    "Escolha um login para liberar ou bloquear uma permissão só para ele, sem mudar o nível inteiro. \"Padrão\" segue o que está marcado para o nível dele.": "Elegí un login para habilitar o bloquear un permiso solo para él, sin cambiar todo el nivel. \"Estándar\" sigue lo que está marcado para su nivel.",
