    "Devolver {qtd} contatos para o Banco Bruto?\n\n{resumo}\n\nSó voltam contatos de lista sem próximo contato marcado (os mais parados primeiro); visitantes ficam. Com muitos contatos, prefira fazer fora do horário de movimento.": "¿Devolver {qtd} contactos al Banco Bruto?\n\n{resumo}\n\nSolo vuelven contactos de lista sin próximo contacto agendado (los más parados primero); los visitantes quedan. Con muchos contactos, mejor hacerlo fuera del horario de movimiento.",
