    // Pendências: domingo sem movimentação e só o dia atual (09/11/2026)
    "Sábado": "Sábado",
    "último lançamento: {data}": "último registro: {data}",
    "nenhum lançamento": "ningún registro",
    "Movimentação: de segunda a sábado (feriado também), a partir das 7h; domingo não tem. Aqui aparece só o dia atual (os dias antigos ficam na tabela Movimentação por dia). Conferência: toda sexta-feira; o mês anterior é cobrado até o dia 15 (pagamento da comissão). Metas: até o dia 03 de cada mês. Relatório da recepção: manhã das 13h30 às 15h, noite das 21h30 às 23h, sábado, domingo e feriado das 12h às 13h.": "Movimiento: de lunes a sábado (feriado también), desde las 7h; el domingo no hay. Acá aparece solo el día actual (los días anteriores quedan en la tabla Movimiento por día). Control: todos los viernes; el mes anterior se cobra hasta el día 15 (pago de la comisión). Metas: hasta el día 03 de cada mes. Informe de recepción: mañana de 13h30 a 15h, noche de 21h30 a 23h, sábado, domingo y feriado de 12h a 13h.",
    "Movimentação: de segunda a sábado (feriado também), a partir das 7h; domingo não tem. Aqui aparece só o dia atual (os dias antigos ficam na tabela Movimentação por dia). Conferência: toda sexta-feira; o mês anterior é cobrado até o dia 15 (pagamento da comissão). Metas: até o dia 03 de cada mês. Relatório da recepção: manhã das 13h30 às 15h, noite das 21h30 às 23h, sábado, domingo e feriado das 12h às 13h. O relatório de ontem aparece o dia todo se ontem foi dia de semana; se foi sábado, domingo ou feriado, só até as 9h.": "Movimiento: de lunes a sábado (feriado también), desde las 7h; el domingo no hay. Acá aparece solo el día actual (los días anteriores quedan en la tabla Movimiento por día). Control: todos los viernes; el mes anterior se cobra hasta el día 15 (pago de la comisión). Metas: hasta el día 03 de cada mes. Informe de recepción: mañana de 13h30 a 15h, noche de 21h30 a 23h, sábado, domingo y feriado de 12h a 13h. El informe de ayer aparece todo el día si ayer fue día de semana; si fue sábado, domingo o feriado, solo hasta las 9h.",
    "Movimentação: de segunda a sábado (feriado também), a partir das 7h; domingo não tem. Conferência: toda sexta-feira; o mês anterior é cobrado até o dia 15 (pagamento da comissão). Metas: até o dia 03 de cada mês. Relatório da recepção: manhã das 13h30 às 15h, noite das 21h30 às 23h, sábado, domingo e feriado das 12h às 13h.": "Movimiento: de lunes a sábado (feriado también), desde las 7h; el domingo no hay. Control: todos los viernes; el mes anterior se cobra hasta el día 15 (pago de la comisión). Metas: hasta el día 03 de cada mes. Informe de recepción: mañana de 13h30 a 15h, noche de 21h30 a 23h, sábado, domingo y feriado de 12h a 13h.",
